/**
 * Adapts operator parameter schemas (generated by Python introspection) for RJSF.
 *
 * - Nullable unions (`type: [x, "null"]`, `anyOf: [X, {type: null}]`) collapse to X:
 *   leaving a field empty already means "not set".
 * - Defaults move into placeholders so untouched fields are NOT written into the spec
 *   (the operator's own default applies at runtime).
 * - Parameters that take Python objects (callables, classes) are given as Python references
 *   (`{"$type": "import", "path": "pkg.module.name"}`).
 * - `x-autoair-*` hints become RJSF `uiSchema` widgets.
 */

export type JsonSchema = {
  type?: string | string[];
  anyOf?: JsonSchema[];
  oneOf?: JsonSchema[];
  properties?: Record<string, JsonSchema>;
  required?: string[];
  items?: JsonSchema;
  default?: unknown;
  title?: string;
  description?: string;
  enum?: unknown[];
  $ref?: string;
  $defs?: Record<string, JsonSchema>;
  additionalProperties?: boolean | JsonSchema;
  "x-autoair-templated"?: boolean;
  "x-autoair-renderer"?: string;
  /** Editor hint: introspection (connection, pool) or catalog/package overrides (the rest). */
  "x-autoair-widget"?: CatalogWidget;
  /** Hidden from the params form by a catalog override (a set value is kept). */
  "x-autoair-hidden"?: boolean;
  "x-autoair-conn-type"?: string[];
  "x-autoair-unsupported"?: string;
  /** "required": only a Python reference can express it; "optional": a reference is also accepted. */
  "x-autoair-python-ref"?: "required" | "optional";
  [key: string]: unknown;
};

export type UiSchema = Record<string, Record<string, unknown>>;

/** `x-autoair-widget` values (catalog.param_overrides / package metadata `widget`). */
export type CatalogWidget =
  | "sql"
  | "bash"
  | "python"
  | "json"
  | "yaml"
  | "markdown"
  | "connection"
  | "variable"
  | "pool"
  | "enum"
  | "secret"
  | "text";

/** Widgets edited in a code editor; the widget name is the language. */
const CODE_WIDGETS = new Set<string>(["sql", "bash", "python", "yaml", "markdown"]);

const SCALAR_ORDER = ["string", "integer", "number", "boolean", "array", "object"];

function collapseNullable(schema: JsonSchema): JsonSchema {
  const out: JsonSchema = { ...schema };
  if (Array.isArray(out.type)) {
    const types = out.type.filter((t) => t !== "null");
    const pick = SCALAR_ORDER.find((t) => types.includes(t)) ?? types[0];
    if (pick) out.type = pick;
    else delete out.type;
  }
  for (const key of ["anyOf", "oneOf"] as const) {
    const variants = out[key];
    if (!variants) continue;
    const nonNull = variants.filter((v) => v.type !== "null");
    if (nonNull.length === 1) {
      out[key] = undefined;
      Object.assign(out, collapseNullable(nonNull[0] as JsonSchema), {
        title: schema.title,
        description: schema.description,
      });
    } else {
      out[key] = nonNull;
    }
  }
  if (out.items) out.items = collapseNullable(out.items);
  for (const key of ["anyOf", "oneOf"] as const) if (out[key] === undefined) Reflect.deleteProperty(out, key);
  if (out.type === undefined && !out.anyOf && !out.oneOf && !out.$ref && !out.enum) {
    // Unknown type: edit as text; templated strings are the common case.
    out.type = "string";
  }
  return out;
}

function placeholderOf(value: unknown): string | undefined {
  if (value === undefined || value === null) return undefined;
  return `default: ${typeof value === "string" ? value : JSON.stringify(value)}`;
}

export function toFormSchema(schema: JsonSchema): { schema: JsonSchema; uiSchema: UiSchema } {
  const properties: Record<string, JsonSchema> = {};
  const uiSchema: UiSchema = {};
  for (const [name, raw] of Object.entries(schema.properties ?? {})) {
    if (raw["x-autoair-unsupported"]) continue;
    if (raw["x-autoair-hidden"] === true) continue;
    const prop = collapseNullable(raw);
    const ui: Record<string, unknown> = {};
    const placeholder = placeholderOf(prop.default);
    delete prop.default;
    if (placeholder) ui["ui:placeholder"] = placeholder;

    const renderer = prop["x-autoair-renderer"];
    const hint = prop["x-autoair-widget"];
    if (hint === "connection") ui["ui:widget"] = "connection";
    else if (hint === "pool") ui["ui:widget"] = "pool";
    else if (hint === "variable") ui["ui:widget"] = "variable";
    else if (hint && CODE_WIDGETS.has(hint)) ui["ui:widget"] = "code";
    else if (hint === "secret") ui["ui:widget"] = "password";
    else if (
      hint !== "text" &&
      prop.type === "string" &&
      renderer &&
      ["bash", "sql", "python", "yaml", "markdown"].includes(renderer)
    ) {
      ui["ui:widget"] = "code";
    }
    if (prop["x-autoair-templated"]) {
      prop.title = `${prop.title ?? name} · Jinja`;
    }
    if ((prop.type === "object" && !prop.properties) || prop.anyOf || prop.oneOf) {
      // Free-form dicts / unions are edited as raw JSON.
      ui["ui:field"] = "json";
    }
    properties[name] = prop;
    if (Object.keys(ui).length) uiSchema[name] = ui;
  }
  const required = (schema.required ?? []).filter((r) => r in properties);
  const out: JsonSchema = { type: "object", properties };
  if (required.length) out.required = required;
  if (schema.$defs) out.$defs = schema.$defs;
  return { schema: out, uiSchema };
}

/** Drop keys whose value is undefined/empty string so the spec only holds set values. */
export function compactParams(data: Record<string, unknown> | undefined): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(data ?? {})) {
    if (v === undefined || v === "") continue;
    out[k] = v;
  }
  return out;
}

/* ------------------------------------------------------------------ params form model */

/** BaseSensorOperator params shown in a dedicated "Sensor" section. */
const SENSOR_PARAMS = [
  "mode",
  "poke_interval",
  "timeout",
  "soft_fail",
  "exponential_backoff",
  "max_wait",
  "silent_fail",
  "never_fail",
] as const;

export type ParamWidget =
  | "text"
  | "code"
  | "integer"
  | "number"
  | "boolean"
  | "enum"
  | "connection"
  | "pool"
  | "variable"
  | "secret"
  | "string-list"
  | "json";

export type ParamGroup = "main" | "sensor" | "deferrable";

/** A top-level operator / notifier parameter, normalised for the params form. */
export type ParamField = {
  name: string;
  title: string;
  description?: string | undefined;
  /** Nullable unions collapsed. */
  schema: JsonSchema;
  widget: ParamWidget;
  /** Jinja-templated (operator `template_fields`). */
  templated: boolean;
  /** Code renderer (bash, sql, python, yaml, json, markdown…). */
  renderer?: string | undefined;
  /** Connection types accepted by a `*_conn_id` param. */
  connTypes: string[];
  required: boolean;
  hasDefault: boolean;
  default?: unknown;
  enumValues?: unknown[] | undefined;
  group: ParamGroup;
  /** Takes a Python object: "required" = only expressible as a Python reference. */
  pythonRef: "required" | "optional" | null;
  /** Python type for the label (`int`, `str | list[str]`, `timedelta`…), `None` omitted. */
  dtype: string | undefined;
  /** Hidden by a catalog override: not rendered, a set value is kept. */
  hidden: boolean;
};

const JSON_TO_PY: Record<string, string> = {
  string: "str",
  integer: "int",
  number: "float",
  boolean: "bool",
  object: "dict",
  array: "list",
  null: "None",
};

/** JSON Schema → Python-ish type text: `{"anyOf":[{"type":"string"},{"type":"array","items":{"type":"string"}}]}` → `str | list[str]`. */
function schemaTypeText(schema: JsonSchema | undefined, depth = 0): string | undefined {
  if (!schema || depth > 3) return undefined;
  const variants = schema.anyOf ?? schema.oneOf;
  if (variants?.length) {
    const parts = [...new Set(variants.map((v) => schemaTypeText(v, depth + 1)).filter((t): t is string => !!t))];
    return parts.length ? parts.join(" | ") : undefined;
  }
  if (schema.enum?.length) return "Literal";
  const types = Array.isArray(schema.type) ? schema.type : schema.type ? [schema.type] : [];
  if (!types.length) return undefined;
  return types
    .map((t) => {
      if (t === "array") {
        const item = schemaTypeText(schema.items, depth + 1);
        return item ? `list[${item}]` : "list";
      }
      if (t === "string" && schema.format === "date-time") return "datetime";
      return JSON_TO_PY[t] ?? t;
    })
    .join(" | ");
}

const SENTINEL_TYPES = new Set(["None", "NoneType", "ArgNotSet", "ArgNotSetType", "NotSet", "NOTSET"]);

/** The label type of a parameter: its Python annotation when known, else from the schema. */
function paramTypeText(raw: JsonSchema): string | undefined {
  const annotation = raw["x-autoair-annotation"];
  const text = typeof annotation === "string" && annotation ? annotation : schemaTypeText(raw);
  if (!text) return undefined;
  // None (shown by the missing *) and Airflow's "argument not set" sentinels are noise.
  const parts = text.split(/\s*\|\s*/).filter((p) => !SENTINEL_TYPES.has(p));
  return parts.length ? parts.join(" | ") : text;
}

const CODE_RENDERERS = new Set(["bash", "sql", "python", "yaml", "json", "markdown", "py", "md"]);

function widgetFor(prop: JsonSchema): ParamWidget {
  const hint = prop["x-autoair-widget"];
  switch (hint) {
    case "connection":
    case "pool":
    case "variable":
    case "secret":
    case "json":
    case "text":
      return hint;
    case "enum":
      return prop.enum?.length ? "enum" : "text";
    default:
      if (hint && CODE_WIDGETS.has(hint)) return "code";
  }
  if (prop.enum?.length) return "enum";
  if (prop.anyOf || prop.oneOf) return "json";
  const renderer = prop["x-autoair-renderer"];
  switch (prop.type) {
    case "string":
      return renderer && CODE_RENDERERS.has(renderer) ? "code" : "text";
    case "integer":
      return "integer";
    case "number":
      return "number";
    case "boolean":
      return "boolean";
    case "array":
      return prop.items?.type === "string" && !prop.items.enum ? "string-list" : "json";
    default:
      return "json";
  }
}

/**
 * Normalises a catalog params schema into ordered form fields: required first (schema
 * order otherwise), sensor base params grouped when `isSensor`, `deferrable` pulled out
 * when the operator supports it. Callable params are kept (edited as Python references).
 */
export function paramFields(
  schema: JsonSchema,
  opts: { isSensor?: boolean | undefined; deferrable?: boolean | undefined } = {},
): ParamField[] {
  const required = new Set(schema.required ?? []);
  const sensor = new Set<string>(SENSOR_PARAMS);
  const out: ParamField[] = [];
  for (const [name, raw] of Object.entries(schema.properties ?? {})) {
    const pythonRef = raw["x-autoair-unsupported"] ? "required" : (raw["x-autoair-python-ref"] ?? null);
    const prop = collapseNullable(raw);
    const hint = prop["x-autoair-widget"];
    // A code widget override names the language; "text" drops the introspected renderer.
    const renderer = hint && CODE_WIDGETS.has(hint) ? hint : hint === "text" ? undefined : prop["x-autoair-renderer"];
    const group: ParamGroup =
      opts.deferrable && name === "deferrable" ? "deferrable" : opts.isSensor && sensor.has(name) ? "sensor" : "main";
    out.push({
      name,
      // An explicit label (catalog.param_overrides / package metadata) is shown as given.
      title:
        typeof raw["x-autoair-label"] === "string" && raw["x-autoair-label"]
          ? raw["x-autoair-label"]
          : raw.title && raw.title.toLowerCase().replace(/ /g, "_") !== name
            ? raw.title
            : name,
      description: raw.description ?? prop.description,
      schema: prop,
      widget: widgetFor(prop),
      templated: !!prop["x-autoair-templated"],
      renderer: typeof renderer === "string" ? renderer : undefined,
      connTypes: Array.isArray(prop["x-autoair-conn-type"]) ? prop["x-autoair-conn-type"] : [],
      required: required.has(name),
      hasDefault: "default" in raw && raw.default !== undefined,
      default: raw.default,
      enumValues: prop.enum,
      group,
      pythonRef,
      dtype: paramTypeText(raw),
      hidden: raw["x-autoair-hidden"] === true,
    });
  }
  const rank = (f: ParamField) => (f.required ? 0 : 1);
  return out
    .map((f, i) => ({ f, i }))
    .sort((a, b) => rank(a.f) - rank(b.f) || a.i - b.i)
    .map(({ f }) => f);
}

/**
 * Fills required params that are not set yet with a *real* default only: the schema default,
 * `false` for a boolean, the only value of a one-value enum. Others (no default) stay unset —
 * an empty placeholder would hide the problem and deploy a task that fails at runtime.
 */
export function fillRequired(
  fields: ParamField[],
  value: Record<string, unknown>,
): { value: Record<string, unknown>; unfilled: string[] } {
  const next = { ...value };
  const unfilled: string[] = [];
  for (const f of fields) {
    if (!f.required || (next[f.name] !== undefined && next[f.name] !== "")) continue;
    if (f.hasDefault && f.default !== null && f.default !== "") next[f.name] = f.default;
    else if (f.widget === "boolean") next[f.name] = false;
    else if (f.widget === "enum" && f.enumValues?.length === 1) next[f.name] = f.enumValues[0];
    else unfilled.push(f.name);
  }
  return { value: next, unfilled };
}

/** How a parameter value is expressed. */
export type ParamMode = "literal" | "xcom" | "template" | "python" | "function" | "file";

export type InlineFunctionValue = { $type: "function"; source: string };
export type FileAssetValue = { $type: "file"; name: string; content: string; run_with?: string | null };
export const isInlineFunction = (v: unknown): v is InlineFunctionValue =>
  typeof v === "object" && v !== null && (v as { $type?: unknown }).$type === "function";
export const isFileAsset = (v: unknown): v is FileAssetValue =>
  typeof v === "object" && v !== null && (v as { $type?: unknown }).$type === "file";

/** Starter function for a param that takes a callable. */
export function functionTemplate(param: string): string {
  const name = param.replace(/_callable$|_function$|^python_/g, "") || "run";
  return `def ${/^[A-Za-z_]\w*$/.test(name) ? name : "run"}(**context):\n    """Called by the operator with the task context."""\n    return None\n`;
}

/** Starter script for a param (Spark application, bash command, SQL file…). */
export function scriptTemplate(param: string): FileAssetValue {
  if (param === "bash_command")
    return {
      $type: "file",
      name: "script.sh",
      content: '#!/usr/bin/env bash\nset -euo pipefail\n\necho "hello"\n',
      run_with: "bash",
    };
  if (/sql/i.test(param)) return { $type: "file", name: "query.sql", content: "SELECT 1;\n" };
  return {
    $type: "file",
    name: "job.py",
    content: "from pyspark.sql import SparkSession\n\nspark = SparkSession.builder.getOrCreate()\n",
  };
}

export type PythonRefValue = { $type: "import"; path: string };
/** `pkg.module.name`: identifiers only (what the server accepts). */
export const PYTHON_PATH_RE = /^[A-Za-z_][A-Za-z0-9_]*(\.[A-Za-z_][A-Za-z0-9_]*)+$/;
export const isPythonRef = (v: unknown): v is PythonRefValue =>
  typeof v === "object" && v !== null && (v as { $type?: unknown }).$type === "import";

export const hasJinja = (v: unknown): v is string => typeof v === "string" && /\{\{|\{%/.test(v);

/** Current mode of a value (templated fields: template text is still a "literal"). */
export function paramMode(
  field: Pick<ParamField, "templated"> & { pythonRef?: ParamField["pythonRef"] },
  value: unknown,
): ParamMode {
  if (typeof value === "object" && value !== null && (value as { $type?: unknown }).$type === "xcom") return "xcom";
  if (isInlineFunction(value)) return "function";
  if (isFileAsset(value)) return "file";
  if (isPythonRef(value) || (field.pythonRef === "required" && (value === undefined || value === ""))) return "python";
  if (!field.templated && hasJinja(value)) return "template";
  return "literal";
}

/** Copy of `obj` without `key`. */
export function withoutKey<T extends object>(obj: T, key: PropertyKey): T {
  return Object.fromEntries(Object.entries(obj).filter(([k]) => k !== key)) as T;
}
